CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (
 id UUID PRIMARY KEY DEFAULT gen_random_uuid(), email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL,
 role TEXT NOT NULL DEFAULT 'visitor' CHECK (role IN ('visitor','admin')), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE TABLE IF NOT EXISTS attractions (
 id TEXT PRIMARY KEY, name_vi TEXT NOT NULL, name_en TEXT NOT NULL, description_vi TEXT NOT NULL, description_en TEXT NOT NULL,
 narration_vi TEXT NOT NULL, narration_en TEXT NOT NULL, area_vi TEXT NOT NULL DEFAULT 'Khuôn viên', area_en TEXT NOT NULL DEFAULT 'Grounds',
 latitude DOUBLE PRECISION, longitude DOUBLE PRECISION, sort_order INTEGER NOT NULL DEFAULT 0, duration_minutes INTEGER NOT NULL DEFAULT 2,
 image_url TEXT, source_url TEXT, visible BOOLEAN NOT NULL DEFAULT TRUE, narration_published BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE TABLE IF NOT EXISTS tours (id TEXT PRIMARY KEY, name_vi TEXT NOT NULL, name_en TEXT NOT NULL, description_vi TEXT NOT NULL, description_en TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tour_stops (tour_id TEXT REFERENCES tours(id) ON DELETE CASCADE, attraction_id TEXT REFERENCES attractions(id) ON DELETE CASCADE, stop_order INTEGER NOT NULL, PRIMARY KEY(tour_id, attraction_id));
CREATE TABLE IF NOT EXISTS feedback (
 id UUID PRIMARY KEY DEFAULT gen_random_uuid(), attraction_id TEXT REFERENCES attractions(id), rating INTEGER CHECK (rating BETWEEN 1 AND 5),
 message TEXT NOT NULL CHECK (char_length(message) <= 1000), type TEXT NOT NULL DEFAULT 'review' CHECK (type IN ('review','accuracy','audio','location')),
 status TEXT NOT NULL DEFAULT 'new' CHECK (status IN ('new','reviewing','resolved')), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE TABLE IF NOT EXISTS narration_assets (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), attraction_id TEXT REFERENCES attractions(id) ON DELETE CASCADE, language TEXT NOT NULL CHECK(language IN ('vi','en')), audio_url TEXT, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(attraction_id, language));
CREATE INDEX IF NOT EXISTS idx_attractions_visible_order ON attractions(visible, sort_order);
CREATE INDEX IF NOT EXISTS idx_feedback_created ON feedback(created_at DESC);
CREATE TABLE IF NOT EXISTS visitor_events (
 id BIGSERIAL PRIMARY KEY,
 visitor_id UUID NOT NULL,
 event_type TEXT NOT NULL CHECK (event_type IN ('app_opened','qr_scan','place_opened','visit_marked','narration_started','narration_completed')),
 attraction_id TEXT REFERENCES attractions(id) ON DELETE CASCADE,
 language TEXT NOT NULL CHECK (language IN ('vi','en')),
 metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
 created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_visitor_events_created_at ON visitor_events(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_visitor_events_visitor_created ON visitor_events(visitor_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_visitor_events_attraction_type ON visitor_events(attraction_id,event_type,created_at DESC);

INSERT INTO attractions(id,name_vi,name_en,description_vi,description_en,narration_vi,narration_en,area_vi,area_en,latitude,longitude,sort_order,duration_minutes,source_url) VALUES
('main-building','Tòa nhà chính','Main Building','Công trình trung tâm của Dinh Độc Lập.','The central building of Independence Palace.','Dinh Độc Lập là một công trình kiến trúc nổi bật tại Thành phố Hồ Chí Minh, gắn với nhiều dấu mốc quan trọng của lịch sử Việt Nam hiện đại. Khi tham quan, bạn hãy chú ý bố cục tổng thể, các khoảng sân và sự kết nối giữa không gian trong nhà với khuôn viên. Nội dung này là phần giới thiệu mẫu và cần được đối chiếu với thuyết minh chính thức.','Independence Palace is a prominent landmark in Ho Chi Minh City associated with important moments in modern Vietnamese history. As you explore, notice the overall layout, courtyards, and the relationship between the interior spaces and the grounds. This is sample introductory narration and should be checked against official visitor materials.','Tòa nhà chính','Main Building',10.7769,106.6953,1,3,'https://independencepalace.gov.vn/'),
('front-lawn','Thảm cỏ phía trước','Front Lawn','Không gian mở phía trước công trình.','The open lawn in front of the building.','Thảm cỏ phía trước tạo khoảng nhìn rộng hướng về mặt tiền công trình. Đây cũng là nơi dễ quan sát hình khối kiến trúc và trục tiếp cận chính. Hãy di chuyển theo lối dành cho khách tham quan và tuân thủ hướng dẫn tại chỗ.','The front lawn creates an open view toward the building facade. It is a good place to observe the architecture and the main approach. Please use visitor paths and follow on-site instructions.','Khuôn viên','Grounds',10.7764,106.6951,2,2,'https://independencepalace.gov.vn/'),
('helicopter-pad','Sân đáp trực thăng','Helicopter Pad','Khu vực sân thượng có sân đáp trực thăng.','The rooftop area featuring a helicopter pad.','Sân đáp trực thăng là một chi tiết dễ nhận biết trong hình ảnh về Dinh Độc Lập. Khi tìm hiểu khu vực này, hãy tham khảo bảng thông tin tại điểm trưng bày để biết thêm bối cảnh và công năng của không gian.','The helicopter pad is a recognizable feature in photographs of Independence Palace. Consult the exhibit information on site for additional context about this space and its use.','Tầng thượng','Rooftop',10.7770,106.6955,3,2,'https://independencepalace.gov.vn/'),
('conference-room','Phòng khánh tiết','Ceremonial Hall','Không gian tiếp đón và tổ chức sự kiện.','A space used for receptions and events.','Phòng khánh tiết là một trong những không gian tiêu biểu phục vụ hoạt động tiếp đón và nghi lễ. Khi quan sát nội thất, bạn có thể chú ý cách bố trí chỗ ngồi, ánh sáng và các chi tiết trang trí. Vui lòng kiểm tra chú giải chính thức để xác định chính xác niên đại và chức năng từng hạng mục.','The ceremonial hall is a representative space for receptions and formal events. Notice the seating arrangement, lighting, and decorative details. Please consult official exhibit labels for precise dates and functions of individual features.','Tầng 1','Floor 1',10.7768,106.6954,4,2,'https://independencepalace.gov.vn/'),
('cabinet-room','Phòng họp nội các','Cabinet Room','Không gian gắn với hoạt động họp và điều hành.','A room associated with meetings and administration.','Phòng họp cho thấy một khía cạnh trong cách tổ chức công việc của bộ máy chính quyền thời kỳ trước. Bố trí bàn ghế và các vật dụng trưng bày giúp hình dung không khí làm việc của một cuộc họp. Hãy dựa vào bảng thuyết minh tại chỗ để tìm hiểu các sự kiện cụ thể.','The meeting room offers a glimpse into the administration and working practices of an earlier period. Its table, seating, and displayed objects help visitors imagine a formal meeting. Refer to the on-site labels for specific historical events.','Tầng 1','Floor 1',10.7769,106.6952,5,2,'https://independencepalace.gov.vn/'),
('basement','Khu tầng hầm','Basement','Khu vực phục vụ hoạt động liên lạc và điều hành.','An area associated with communications and operations.','Khu tầng hầm mang đến góc nhìn khác với các phòng nghi lễ phía trên. Các khu vực và thiết bị được giới thiệu tại đây giúp khách tham quan tìm hiểu hoạt động liên lạc, điều hành trong bối cảnh lịch sử. Nội dung chi tiết nên được kiểm chứng theo bảng trưng bày chính thức.','The basement provides a contrast to the ceremonial rooms above. Exhibits here help visitors learn about communications and operations in their historical context. Please verify detailed information with the official exhibit labels.','Tầng hầm','Basement',10.7766,106.6950,6,3,'https://independencepalace.gov.vn/'),
('garden','Khuôn viên cây xanh','Gardens','Khuôn viên có cây xanh bao quanh công trình.','Green spaces surrounding the building.','Khuôn viên cây xanh tạo môi trường thoáng đãng quanh tòa nhà và góp phần định hình trải nghiệm tham quan. Đây cũng là nơi nghỉ chân phù hợp giữa các điểm trong lộ trình. Hãy đi theo lối quy định và không làm ảnh hưởng đến cảnh quan.','The landscaped grounds create an open setting around the building and shape the visitor experience. They can also provide a quiet pause between stops. Please stay on designated paths and help protect the landscape.','Khuôn viên','Grounds',10.7762,106.6957,7,2,'https://independencepalace.gov.vn/'),
('exhibition','Khu trưng bày','Exhibition Area','Khu vực giới thiệu tư liệu và hình ảnh lịch sử.','An area displaying historical documents and photographs.','Khu trưng bày giúp bổ sung tư liệu cho những không gian kiến trúc bạn đã đi qua. Khi xem hiện vật, hãy đọc phần chú thích để phân biệt tư liệu gốc, hình ảnh minh họa và nội dung diễn giải. Việc chụp ảnh có thể phụ thuộc quy định của từng khu vực.','The exhibition area adds documentary context to the architectural spaces you have visited. Read labels carefully to distinguish original materials, illustrative images, and interpretation. Photography may be subject to area-specific rules.','Khu trưng bày','Exhibition Area',10.7767,106.6956,8,3,'https://independencepalace.gov.vn/')
ON CONFLICT (id) DO NOTHING;
INSERT INTO tours(id,name_vi,name_en,description_vi,description_en) VALUES ('highlights','Lộ trình điểm nổi bật','Highlights Tour','Lộ trình mẫu qua các điểm tiêu biểu.','A sample route through selected highlights.') ON CONFLICT DO NOTHING;
INSERT INTO tour_stops(tour_id,attraction_id,stop_order) VALUES ('highlights','front-lawn',1),('highlights','main-building',2),('highlights','conference-room',3),('highlights','cabinet-room',4),('highlights','basement',5),('highlights','garden',6) ON CONFLICT DO NOTHING;
